// Home-screen app files: the manifest, a small service worker, and the icons.
// They are served by the Worker itself, so there is nothing to host separately.
//
// This is a Progressive Web App, not a store app. On a phone: Share -> Add to Home
// Screen (iOS) or the browser menu -> Add to Home screen / Install (Android). The
// result behaves like an installed app - own icon, own name, no address bar - and
// updates itself whenever you redeploy, with nothing for anyone to re-install.

export const MANIFEST = JSON.stringify({
  name: 'AETRAA',
  short_name: 'AETRAA',
  description: 'Construction project management — progress, records, payments and reports',
  start_url: '/',
  scope: '/',
  display: 'standalone',
  orientation: 'any',
  background_color: '#1E2126',
  theme_color: '#1E2126',
  icons: [
    { src: '/icon-192.png', sizes: '192x192', type: 'image/png', purpose: 'any' },
    { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'any' },
    { src: '/icon-512.png', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
  ],
  shortcuts: [
    { name: 'Site update', short_name: 'Update', url: '/site' },
    { name: 'Portfolio', short_name: 'Portfolio', url: '/portfolio' },
  ],
});

// Deliberately thin. Progress data must never be served stale from a cache, so
// nothing under /api is ever cached - the worker only keeps the app shell so the
// page opens instantly and shows an honest "no connection" screen when offline.
export const SERVICE_WORKER = `
const SHELL = 'sm-shell-v4';
self.addEventListener('install', (e) => self.skipWaiting());
self.addEventListener('activate', (e) => {
  e.waitUntil(caches.keys().then((keys) =>
    Promise.all(keys.filter((k) => k !== SHELL).map((k) => caches.delete(k)))
  ).then(() => self.clients.claim()));
});
self.addEventListener('fetch', (e) => {
  const url = new URL(e.request.url);
  if (e.request.method !== 'GET') return;
  if (url.pathname.startsWith('/api/') || url.pathname.startsWith('/photo/')) return;
  if (url.pathname.match(/\\.(png|ico|webmanifest)$/)) {
    e.respondWith(
      caches.open(SHELL).then((c) =>
        c.match(e.request).then((hit) =>
          hit || fetch(e.request).then((res) => { c.put(e.request, res.clone()); return res; })
        )
      )
    );
  }
});
`;

